import { ref, onMounted, onUnmounted } from 'vue';
import * as echarts from 'echarts';
import axios from 'axios';
import { API_CONFIG } from './config';
export default {
  __name: 'UserDashboard',
  setup(__props, {
    expose: __expose
  }) {
    __expose();
    const genderChart = ref(null);
    const ageChart = ref(null);
    let genderChartInstance = null;
    let ageChartInstance = null;

    // 渲染性别比例分布图表
    const renderGenderChart = async () => {
      try {
        // 向后端请求性别分布数据
        const response = await axios.get(`${API_CONFIG.BASE_URL}/bigdata/gender-distribution`);
        const data = response.data;
        const total = data.male_count + data.female_count;
        genderChartInstance = echarts.init(genderChart.value);
        const option = {
          title: {
            text: `总人数: ${total}`,
            left: '5%',
            top: '5%',
            textStyle: {
              fontSize: 14,
              fontWeight: 'normal',
              color: '#666'
            }
          },
          tooltip: {
            trigger: 'item',
            formatter: params => {
              return `${params.name}: ${params.value}人 (${params.percent}%)`;
            }
          },
          series: [{
            name: '性别分布',
            type: 'pie',
            radius: '70%',
            center: ['50%', '50%'],
            avoidLabelOverlap: false,
            itemStyle: {
              borderColor: '#fff',
              borderWidth: 2
            },
            label: {
              show: true,
              formatter: '{b}: {d}%',
              position: 'outside'
            },
            emphasis: {
              label: {
                show: true,
                fontSize: '14',
                fontWeight: 'bold'
              }
            },
            labelLine: {
              show: true,
              length: 10,
              length2: 15
            },
            data: [{
              value: data.male_count,
              name: '男',
              itemStyle: {
                color: '#1890ff',
                shadowBlur: 10,
                shadowColor: 'rgba(0, 0, 0, 0.3)'
              }
            }, {
              value: data.female_count,
              name: '女',
              itemStyle: {
                color: '#f04864',
                shadowBlur: 10,
                shadowColor: 'rgba(0, 0, 0, 0.3)'
              }
            }]
          }]
        };
        genderChartInstance.setOption(option);
      } catch (error) {
        console.error('获取性别分布数据失败:', error);
      }
    };

    // 渲染年龄分布图表
    const renderAgeChart = async () => {
      try {
        const response = await axios.get(`${API_CONFIG.BASE_URL}/bigdata/age-distribution`);
        const data = response.data;
        ageChartInstance = echarts.init(ageChart.value);
        const option = {
          title: {
            text: '年龄分布',
            left: 'center',
            textStyle: {
              fontSize: 16,
              fontWeight: 'bold'
            }
          },
          tooltip: {
            trigger: 'axis',
            axisPointer: {
              type: 'shadow'
            },
            formatter: function (params) {
              const maleCount = params[0].data;
              const femaleCount = params[1].data;
              const total = maleCount + femaleCount;
              return `
            ${params[0].name}<br/>
            男: ${maleCount}人<br/>
            女: ${femaleCount}人<br/>
            总数: ${total}人
          `;
            }
          },
          legend: {
            data: ['男', '女'],
            top: 30
          },
          grid: {
            left: '3%',
            right: '4%',
            bottom: '3%',
            containLabel: true
          },
          xAxis: {
            type: 'category',
            data: data.age_groups,
            axisLabel: {
              interval: 0,
              rotate: 30
            }
          },
          yAxis: {
            type: 'value',
            name: '人数'
          },
          series: [{
            name: '男',
            type: 'bar',
            stack: 'gender',
            // 使用相同的stack名称实现堆叠
            data: data.male_counts,
            itemStyle: {
              color: '#1890ff',
              borderColor: '#fff',
              borderWidth: 1
            }
          }, {
            name: '女',
            type: 'bar',
            stack: 'gender',
            // 使用相同的stack名称实现堆叠
            data: data.female_counts,
            itemStyle: {
              color: '#f04864',
              borderColor: '#fff',
              borderWidth: 1
            }
          }]
        };
        ageChartInstance.setOption(option);
      } catch (error) {
        console.error('获取年龄分布数据失败:', error);
      }
    };

    // 处理窗口 resize 事件
    const handleResize = () => {
      if (genderChartInstance) genderChartInstance.resize();
      if (ageChartInstance) ageChartInstance.resize();
    };

    // 组件挂载时的生命周期钩子函数
    onMounted(() => {
      renderGenderChart();
      renderAgeChart();
      window.addEventListener('resize', handleResize);
    });

    // 组件卸载时的生命周期钩子函数
    onUnmounted(() => {
      window.removeEventListener('resize', handleResize);
      if (genderChartInstance) {
        genderChartInstance.dispose();
        genderChartInstance = null;
      }
      if (ageChartInstance) {
        ageChartInstance.dispose();
        ageChartInstance = null;
      }
    });
    const __returned__ = {
      genderChart,
      ageChart,
      get genderChartInstance() {
        return genderChartInstance;
      },
      set genderChartInstance(v) {
        genderChartInstance = v;
      },
      get ageChartInstance() {
        return ageChartInstance;
      },
      set ageChartInstance(v) {
        ageChartInstance = v;
      },
      renderGenderChart,
      renderAgeChart,
      handleResize,
      ref,
      onMounted,
      onUnmounted,
      get echarts() {
        return echarts;
      },
      get axios() {
        return axios;
      },
      get API_CONFIG() {
        return API_CONFIG;
      }
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
